import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import { navDateToTime } from "../../utils/nifty";

const toNavPairs = (rows) =>
  rows
    .map(([date, nav]) => [navDateToTime(date), Number(nav)])
    .filter(([time, nav]) => Number.isFinite(time) && Number.isFinite(nav))
    .sort((a, b) => a[0] - b[0]);

// The snapshot is generated by `npm run update:funds`. One request replaces the
// 62 per-fund calls the app used to make on every visit.
const snapshotToItems = (snapshot) => {
  const items = {};

  Object.entries(snapshot?.funds || {}).forEach(([code, fund]) => {
    const navs = toNavPairs(fund?.navs || []);
    items[code] = {
      status: navs.length > 0 ? "succeeded" : "failed",
      navs,
      schemeName: fund?.schemeName || null,
      error: navs.length > 0 ? null : "No NAV data in snapshot",
    };
  });

  return items;
};

export const fetchFundSnapshot = createAsyncThunk("compare/fetchFundSnapshot", async () => {
  const base = import.meta.env.BASE_URL || "/";
  const response = await axios.get(`${base}data/funds.json`);
  return response.data;
});

const initialState = {
  items: {}, // code -> { status, navs, schemeName, error }
  allStatus: "idle",
  meta: null,
  error: null,
};

const compareSlice = createSlice({
  name: "compare",
  initialState,
  reducers: {},
  extraReducers(builder) {
    builder
      .addCase(fetchFundSnapshot.pending, (state) => {
        state.allStatus = "loading";
        state.error = null;
      })
      .addCase(fetchFundSnapshot.fulfilled, (state, action) => {
        state.items = snapshotToItems(action.payload);
        state.allStatus = "succeeded";
        state.meta = {
          source: action.payload?.source || "MFAPI.in",
          fetchedAt: action.payload?.fetchedAt,
          coverage: action.payload?.coverage,
        };
        state.error = null;
      })
      .addCase(fetchFundSnapshot.rejected, (state, action) => {
        state.allStatus = "failed";
        state.error = action.error.message;
      });
  },
});

export const getFundItems = (store) => store.compare.items;
export const getFundsStatus = (store) => store.compare.allStatus;
export const getFundsMeta = (store) => store.compare.meta;

export default compareSlice.reducer;
